template <std::size_t I> struct pfr_lens {
    template <class S> decltype(auto) view(const S& s) const { return boost::pfr::get<I>(s); }
    template <class S, class V> S set(S s, V v) const { boost::pfr::get<I>(s) = std::move(v); return s; }
};

